    hp(d,'r_placentia',{kind:'battle',note:'476年8月28日俄瑞斯忒斯在此被奥多亚克所杀。'});
    hp(d,'ravenna',{kind:'battle',note:'476年9月4日罗慕路斯在此被废。'});
    hp(d,'naples',{note:'被废的罗慕路斯送到海湾边的卢库卢斯别墅，每年领六千金币。'});
    hp(d,'constantinople',{note:'元老院把西部皇帝的冠服和仪仗送到芝诺这里。'});
