    hp(d,'vienne',{note:'普罗旺斯的查理一带的重镇，由他的监护人吉拉尔伯爵替他打理。'});hp(d,'w_pavia',{note:'路易二世的意大利王国都城。'});
    hp(d,'it_palermo');hp(d,'b_bari',{kind:'battle',note:'847年前后成了埃米尔国；866年起路易二世出兵围打。'});
