    hp(d,'an_santiago',{kind:'battle'});hp(d,'an_leon',{kind:'battle',note:'986年、994年两度被曼苏尔攻破。'});
    hp(d,'k_barcelona',{kind:'battle',note:'985年7月被曼苏尔攻破洗劫。'});hp(d,'vg_ceuta',{left:1,note:'931年归科尔多瓦；北非招来的柏柏尔兵多从这一带渡海。'});
