    hp(d,'dunhuang',{left:1,note:'河西四郡最西端，丝绸之路通往西域与大夏（巴克特里亚）、安息的门户。'});
    hr(d,[[34.31,108.90],[36.0,103.8],[38.9,100.4],[40.14,94.66]],HC.route);
