    hp(d,'chibi',{kind:'battle',left:1,note:'208年孙刘联军在此击败曹操，形成三分之势。'});
    hp(d,'luoyi',{left:1,note:'曹魏与西晋都城；八王之乱后，311年永嘉之乱洛阳被匈奴汉国攻破。'});
    hp(d,'jiankang',{note:'孙吴都城建业；280年西晋灭吴于此。'});
